import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ModalFormRequest{FormID: 300, FormData: []byte(`{"type":"modal"}`)}
MODAL = bytes.fromhex("ac02107b2274797065223a226d6f64616c227d")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ModalFormRequest{FormID: 1, FormData: []byte{}}
EMPTY = bytes.fromhex("0100")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ModalFormRequest{FormID: 1, FormData: []byte(strings.Repeat("x", 130))}
LONG = bytes.fromhex(
    "01820178787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
)

GOLDENS = (
    [
        pytest.param(
            v.ModalFormRequestPacket(form_id=300, form_json='{"type":"modal"}'),
            MODAL,
            id=f"{v.__name__.rpartition('.')[2]}-modal",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(v.ModalFormRequestPacket(form_id=1), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty-form-json")
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ModalFormRequestPacket(form_id=1, form_json="x" * 130),
            LONG,
            id=f"{v.__name__.rpartition('.')[2]}-two-byte-length-prefix",
        )
        for v in VERSIONS
    ]
)


@pytest.mark.parametrize("version", VERSIONS)
def test_modal_form_request_is_packet_100(version):
    assert version.PACKETS[100] is version.ModalFormRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_modal_form_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_modal_form_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
